const LanguageContext = React.createContext({
  lang: "en",
  setLang: () => {},
  isRTL: false,
  t: (k, fallback) => fallback || k
});

function formatCurrency(price, activeCountry, lang = "en") {
  if (!activeCountry) return `SAR ${price}`;
  const val = (price * (activeCountry.rate || 1)).toFixed(2);
  if (activeCountry.name === "KSA" || activeCountry.currency === "SAR" || activeCountry.currencyAr === "SAR") {
    return `SAR ${val}`;
  }
  if (lang === "ar") {
    const sym = activeCountry.currencyAr || activeCountry.currency;
    return `${val} ${sym}`;
  }
  return `${activeCountry.currency} ${val}`;
}
// ── Cloudinary CDN config ──────────────────────────────────────────────────
// Sign up free at cloudinary.com and paste your cloud name below.
const CLOUDINARY_CLOUD = ""; // e.g. "khadlaj-perfumes"
const _CDN = CLOUDINARY_CLOUD
  ? `https://res.cloudinary.com/${CLOUDINARY_CLOUD}/image/fetch/f_auto,q_auto`
  : null;

export function resolveAsset(url) {
  if (!url || typeof url !== 'string') return url;
  if (url.startsWith('data:') || url.startsWith('blob:')) return url;
  if (url.startsWith('http://') || url.startsWith('https://')) return url;
  
  const clean = url.split('?')[0];
  const filename = clean.split('/').pop();

  if (typeof window !== 'undefined') {
    if (filename.includes('purple-logo')) {
      return window.__PURPLE_LOGO__ || (window.__THEME_ASSETS__ && window.__THEME_ASSETS__['purple-logo.png']) || PURPLE_LOGO_BASE64;
    }
    if (filename.includes('horizontal-logo')) {
      return window.__HORIZONTAL_LOGO__ || (window.__THEME_ASSETS__ && window.__THEME_ASSETS__['khadlaj-horizontal-logo.png']) || HORIZONTAL_LOGO_BASE64;
    }
    if (filename.includes('desktop hero video') || filename.includes('desktop-hero-video')) {
      return window.__DESKTOP_HERO_VIDEO__ || window.__VIDEO_URL__ || (window.__THEME_ASSETS__ && (window.__THEME_ASSETS__['desktop-hero-video.mp4'] || window.__THEME_ASSETS__['desktop hero video.mp4'])) || "/assets/videos/desktop hero video.mp4";
    }
    if (filename.includes('mobile hero video') || filename.includes('mobile-hero-video')) {
      return window.__MOBILE_HERO_VIDEO__ || window.__MOBILE_VIDEO_URL__ || (window.__THEME_ASSETS__ && (window.__THEME_ASSETS__['mobile hero video.mp4'] || window.__THEME_ASSETS__['mobile-hero-video.mp4'])) || "/assets/videos/mobile hero video.mp4";
    }
    if (filename.includes('giftbanner')) {
      return (window.__THEME_ASSETS__ && window.__THEME_ASSETS__['giftbanner.jpg']) || "/assets/bananer/giftbanner.jpg";
    }
    if (filename.includes('oud collection') || filename.includes('oud-collection') || filename.includes('oudcollection')) {
      return (window.__THEME_ASSETS__ && (window.__THEME_ASSETS__['oud-collection.jpg'] || window.__THEME_ASSETS__['oud collection.jpg'])) || "/assets/images/showcase/oud collection.jpg";
    }
    if (filename.includes('home_ambience_banner') || filename.includes('home-ambience-banner') || filename.includes('homeambience')) {
      return (window.__THEME_ASSETS__ && window.__THEME_ASSETS__['home_ambience_banner.jpg']) || "/assets/images/banners/home_ambience_banner.jpg";
    }
    if (filename.includes('deals_mobile') || filename.includes('DEALS mobile') || filename.includes('deals-mobile') || filename.includes('DEALS%20mobile')) {
      return (window.__THEME_ASSETS__ && (window.__THEME_ASSETS__['deals_mobile.png'] || window.__THEME_ASSETS__['DEALS mobile version.png'])) || "/assets/deals_mobile.png";
    }
    if (window.__THEME_ASSETS__ && window.__THEME_ASSETS__[filename]) {
      return window.__THEME_ASSETS__[filename];
    }
    if (typeof window.__GET_ASSET__ === 'function') {
      const res = window.__GET_ASSET__(url);
      if (res && res !== url) return res;
    }
    if (window.__SHOPIFY_ASSET_BASE__) {
      return window.__SHOPIFY_ASSET_BASE__ + filename;
    }
  }
  return url;
}

function getOptimizedImage(url, width = 600) {
  if (!url || typeof url !== 'string') return url;
  // If it's a theme/local asset or broken github asset, resolve it to Shopify theme CDN!
  if (url.startsWith('/assets/') || url.startsWith('./assets/') || url.includes('hifzatoufiq.github.io')) {
    const resolved = resolveAsset(url);
    if (resolved && resolved !== url) return resolved;
  }
  // Shopify / Khadlaj store CDN — add width & webp params
  if (url.includes('cdn.shopify.com') || url.includes('khadlaj-perfumes.com/cdn')) {
    const sep = url.includes('?') ? '&' : '?';
    if (!url.includes('width=')) return `${url}${sep}width=${width}&format=webp`;
    return url;
  }
  // Cloudinary fetch — auto-format, auto-quality, resize any image
  if (_CDN) {
    const abs = url.startsWith('/') ? (typeof window !== 'undefined' ? window.location.origin : '') + url : url;
    return `${_CDN},w_${width}/${encodeURIComponent(abs)}`;
  }
  return url;
}


