export function cleanDisplayTitle(title) {
  if (!title) return "";
  let clean = title.trim();
  clean = clean.replace(/^khadlaj\s+/i, "");
  clean = clean.replace(/\s*\d+\s*(?:ml|g|gms|gm|oz)\b.*$/i, "");
  clean = clean.replace(/\s*(?:eau\s+de\s+parfum|extrait\s+de\s+parfum|edp\s+spray|edp|cpo|perfume\s+oil).*$/i, "");
  return clean.trim();
}

function getProductName(p, isRTL) {
  if (!p) return "";
  const rawTitle = p.shopifyTitle || p.name || "";
  if (!isRTL) return rawTitle;
  if (p.nameAr) return p.nameAr;
  const cleanTitle = cleanDisplayTitle(rawTitle);
  const orig = (p.originalName || rawTitle).toUpperCase().trim();
  if (PRODUCT_NAMES_AR[orig]) return PRODUCT_NAMES_AR[orig];
  const upper = rawTitle.toUpperCase().trim();
  if (PRODUCT_NAMES_AR[upper]) return PRODUCT_NAMES_AR[upper];
  if (cleanTitle) {
    const cleanUpper = cleanTitle.toUpperCase().trim();
    if (PRODUCT_NAMES_AR[cleanUpper]) return PRODUCT_NAMES_AR[cleanUpper];
  }
  if (PRODUCT_NAMES_AR[p.name]) return PRODUCT_NAMES_AR[p.name];
  return rawTitle;
}

function formatProductSize(size, isRTL) {
  if (!size) return "";
  if (!isRTL) return size;
  return size
    .replace(/100\s*ml\s*edp/gi, "100 مل ماء عطر")
    .replace(/100\s*ml/gi, "100 مل")
    .replace(/50\s*ml/gi, "50 مل")
    .replace(/25\s*ml/gi, "25 مل")
    .replace(/30\s*ml/gi, "30 مل")
    .replace(/20\s*ml/gi, "20 مل")
    .replace(/18\s*ml/gi, "18 مل")
    .replace(/17\s*ml/gi, "17 مل")
    .replace(/Gift Set/gi, "مجموعة هدايا")
    .replace(/EDP/gi, "ماء عطر");
}

