/* ═══════════════════════════════════════════════════════════════
   NEW LAUNCHES FULL-WIDTH BANNER SLIDER (FRESH ULTRA-HD)
═══════════════════════════════════════════════════════════════ */
function NewLaunchesHeroBannerSlider({ setPage, setViewProduct, setSelectedCollection, setCollectionCategory }) {
  const [current, setCurrent] = useState(0);
  const [isPaused, setIsPaused] = useState(false);
  const touchStartX = useRef(0);
  const touchEndX = useRef(0);

  const handleTouchStart = (e) => {
    setIsPaused(true);
    if (e.touches && e.touches[0]) {
      touchStartX.current = e.touches[0].clientX;
    }
  };

  const handleTouchEnd = (e) => {
    setIsPaused(false);
    if (e.changedTouches && e.changedTouches[0]) {
      touchEndX.current = e.changedTouches[0].clientX;
      const diff = touchStartX.current - touchEndX.current;
      if (Math.abs(diff) > 35) {
        if (diff > 0) {
          setCurrent(prev => (prev + 1) % banners.length);
        } else {
          setCurrent(prev => (prev === 0 ? banners.length - 1 : prev - 1));
        }
      }
    }
  };

  const banners = [
    {
      id: "muse",
      img: "/assets/images/banners/muse_desktop.png",
      imgMobile: "/assets/images/banners/muse_mobile.png",
      title: "KHADLAJ MUSE",
      subtitle: "100 ML EAU DE PARFUM",
      badge: "NEW LAUNCH",
      productName: "MUSE",
      productId: 8869598462151
    },
    {
      id: "island-sun",
      img: "/assets/images/banners/island_sun_desktop.png",
      imgMobile: "/assets/images/banners/island_sun_mobile.png",
      title: "ISLAND SUN",
      subtitle: "100 ML EXTRAIT DE PARFUM",
      badge: "NEW LAUNCH",
      productName: "ISLAND SUN",
      productId: 9200000000010
    }
  ];

  useEffect(() => {
    if (isPaused) return;
    const timer = setInterval(() => {
      setCurrent(prev => (prev + 1) % banners.length);
    }, 5000);
    return () => clearInterval(timer);
  }, [isPaused, banners.length]);

  const handleBannerClick = (banner) => {
    if (banner.id === "deals" || banner.collectionKey === "deals") {
      if (setCollectionCategory) setCollectionCategory("Deals");
      if (setSelectedCollection) setSelectedCollection("deals");
      if (setPage) setPage("collections");
      return;
    }
    const prod = PRODUCTS.find(p => p.name === banner.productName || p.id === banner.productId);
    if (prod && setViewProduct) {
      setViewProduct(prod);
      if (setPage) setPage("product");
    } else if (setPage) {
      setPage("collections");
    }
  };

  const prevSlide = (e) => {
    e.stopPropagation();
    setCurrent(prev => (prev === 0 ? banners.length - 1 : prev - 1));
  };

  const nextSlide = (e) => {
    e.stopPropagation();
    setCurrent(prev => (prev + 1) % banners.length);
  };

  return (
    <section 
      style={{
        padding: 0, 
        margin: 0,
        width: "100%",
        background: "#0d0d0d",
        position: "relative",
        overflow: "hidden"
      }}
      onMouseEnter={() => setIsPaused(true)}
      onMouseLeave={() => setIsPaused(false)}
      onTouchStart={handleTouchStart}
      onTouchEnd={handleTouchEnd}
    >
      <div 
        className="banner-slider-container"
        style={{
          position: "relative",
          width: "100%",
          overflow: "hidden",
          background: "#0d0d0d",
          cursor: "pointer",
          transform: "translateZ(0)"
        }}
      >
        {banners.map((b, idx) => (
          <div
            key={b.id}
            onClick={() => handleBannerClick(b)}
            style={{
              position: "absolute",
              inset: 0,
              opacity: current === idx ? 1 : 0,
              transition: "opacity 0.7s ease",
              pointerEvents: current === idx ? "auto" : "none",
              display: "flex",
              alignItems: "center",
              justifyContent: "center",
              transform: "translateZ(0)"
            }}
          >
            <picture style={{width:"100%", height:"100%", display:"block"}}>
              {b.imgMobile && <source media="(max-width: 767px)" srcSet={resolveAsset(b.imgMobile)} />}
              <img
                src={resolveAsset(b.img)}
                alt={b.title}
                className="banner-slide-img"
                onError={(e) => {
                  const isMob = typeof window !== 'undefined' && window.innerWidth <= 767;
                  const chosenImg = (isMob && b.imgMobile) ? b.imgMobile : b.img;
                  const fname = chosenImg.split('/').pop();
                  const fb = (window.__THEME_ASSETS__ && window.__THEME_ASSETS__[fname]) || (window.__SHOPIFY_ASSET_BASE__ && (window.__SHOPIFY_ASSET_BASE__ + fname));
                  if (fb && fb !== e.currentTarget.src) e.currentTarget.src = fb;
                }}
                style={{
                  width: "100%",
                  height: "100%",
                  objectFit: "cover",
                  objectPosition: "center center",
                  display: "block",
                  WebkitBackfaceVisibility: "hidden",
                  transform: "translateZ(0)"
                }}
              />
            </picture>
          </div>
        ))}

        {/* Navigation Arrows */}
        <button
          onClick={prevSlide}
          aria-label="Previous Slide"
          className="banner-arrow-btn banner-arrow-prev"
          style={{
            position: "absolute",
            left: "20px",
            top: "50%",
            transform: "translateY(-50%)",
            zIndex: 10,
            width: "44px",
            height: "44px",
            borderRadius: "50%",
            background: "rgba(255, 255, 255, 0.85)",
            backdropFilter: "blur(8px)",
            WebkitBackdropFilter: "blur(8px)",
            border: "1px solid rgba(255,255,255,0.5)",
            boxShadow: "0 4px 15px rgba(0,0,0,0.2)",
            color: "#251737",
            display: "flex",
            alignItems: "center",
            justifyContent: "center",
            cursor: "pointer",
            transition: "all 0.3s ease"
          }}
          onMouseEnter={(e) => {
            e.currentTarget.style.background = "#251737";
            e.currentTarget.style.color = "#fff";
            e.currentTarget.style.transform = "translateY(-50%) scale(1.1)";
          }}
          onMouseLeave={(e) => {
            e.currentTarget.style.background = "rgba(255, 255, 255, 0.85)";
            e.currentTarget.style.color = "#251737";
            e.currentTarget.style.transform = "translateY(-50%) scale(1)";
          }}
        >
          <svg width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.2" strokeLinecap="round" strokeLinejoin="round">
            <path d="M15 18l-6-6 6-6" />
          </svg>
        </button>

        <button
          onClick={nextSlide}
          aria-label="Next Slide"
          className="banner-arrow-btn banner-arrow-next"
          style={{
            position: "absolute",
            right: "20px",
            top: "50%",
            transform: "translateY(-50%)",
            zIndex: 10,
            width: "44px",
            height: "44px",
            borderRadius: "50%",
            background: "rgba(255, 255, 255, 0.85)",
            backdropFilter: "blur(8px)",
            WebkitBackdropFilter: "blur(8px)",
            border: "1px solid rgba(255,255,255,0.5)",
            boxShadow: "0 4px 15px rgba(0,0,0,0.2)",
            color: "#251737",
            display: "flex",
            alignItems: "center",
            justifyContent: "center",
            cursor: "pointer",
            transition: "all 0.3s ease"
          }}
          onMouseEnter={(e) => {
            e.currentTarget.style.background = "#251737";
            e.currentTarget.style.color = "#fff";
            e.currentTarget.style.transform = "translateY(-50%) scale(1.1)";
          }}
          onMouseLeave={(e) => {
            e.currentTarget.style.background = "rgba(255, 255, 255, 0.85)";
            e.currentTarget.style.color = "#251737";
            e.currentTarget.style.transform = "translateY(-50%) scale(1)";
          }}
        >
          <svg width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.2" strokeLinecap="round" strokeLinejoin="round">
            <path d="M9 18l6-6-6-6" />
          </svg>
        </button>

        {/* Indicators / Dots */}
        <div 
          className="banner-indicators"
          style={{
            position: "absolute",
            bottom: "16px",
            left: "50%",
            transform: "translateX(-50%)",
            zIndex: 10,
            display: "flex",
            gap: "8px",
            alignItems: "center",
            background: "rgba(0, 0, 0, 0.35)",
            backdropFilter: "blur(6px)",
            WebkitBackdropFilter: "blur(6px)",
            padding: "6px 12px",
            borderRadius: "20px"
          }}
        >
          {banners.map((_, idx) => (
            <button
              key={idx}
              onClick={(e) => {
                e.stopPropagation();
                setCurrent(idx);
              }}
              aria-label={`Go to slide ${idx + 1}`}
              style={{
                width: current === idx ? "26px" : "8px",
                height: "8px",
                borderRadius: "4px",
                background: current === idx ? "#B8922A" : "rgba(255, 255, 255, 0.65)",
                border: "none",
                cursor: "pointer",
                transition: "all 0.3s ease",
                padding: 0
              }}
            />
          ))}
        </div>
      </div>
    </section>
  );
}

