          background: "linear-gradient(135deg, #251737 0%, #150921 100%)",
          color: "#fff",
          width: 52,
          height: 52,
          borderRadius: "50%",
          border: "1.5px solid #D4AF37",
          cursor: "pointer",
          boxShadow: "0 10px 30px rgba(37,23,55,0.45)",
